export type OrderStatus =
  | 'new'
  | 'confirmed'
  | 'preparing'
  | 'delivering'
  | 'delivered'
  | 'cancelled';

export type PaymentStatus = 'paid' | 'pending' | 'refunded';

export interface Category {
  id: string;
  name: string;
  icon: string;
  description: string;
  color: string;
}

export interface Product {
  id: string;
  name: string;
  sku: string;
  categoryId: string;
  price: number;
  oldPrice?: number;
  unit: string;
  stock: number;
  emoji: string;
  gradient: string;
  description: string;
  active: boolean;
  sold: number;
  rating: number;
}

export interface OrderItem {
  productId: string;
  name: string;
  qty: number;
  price: number;
  emoji: string;
}

export interface Order {
  id: string;
  customerId: string;
  customer: string;
  phone: string;
  address: string;
  items: OrderItem[];
  subtotal: number;
  deliveryFee: number;
  discount: number;
  total: number;
  status: OrderStatus;
  payment: PaymentStatus;
  method: 'card' | 'cash';
  courierId?: string;
  createdAt: string;
  eta: string;
  note?: string;
  x: number;
  y: number;
}

export interface Courier {
  id: string;
  name: string;
  phone: string;
  vehicle: 'Bike' | 'Scooter' | 'Car';
  status: 'online' | 'busy' | 'offline';
  deliveries: number;
  activeOrders: number;
  rating: number;
  x: number;
  y: number;
  emoji: string;
}

export interface Customer {
  id: string;
  name: string;
  phone: string;
  email: string;
  orders: number;
  spent: number;
  joined: string;
  vip: boolean;
  blocked: boolean;
  emoji: string;
}

export interface Promotion {
  id: string;
  code: string;
  type: 'percentage' | 'fixed';
  value: number;
  minOrder: number;
  validUntil: string;
  uses: number;
  maxUses: number;
  active: boolean;
}

export interface Payment {
  id: string;
  orderId: string;
  customer: string;
  amount: number;
  method: 'card' | 'cash';
  status: PaymentStatus;
  date: string;
}

export interface StaffMember {
  id: string;
  name: string;
  role: 'manager' | 'operator' | 'courier';
  department: string;
  email: string;
  phone: string;
  hired: string;
  active: boolean;
  emoji: string;
}

