const item = (productId: string, qty: number): OrderItem => {
  const p = initialProducts.find((x) => x.id === productId)!;
  return { productId, name: p.name, qty, price: p.price, emoji: p.emoji };
};

const mk = (
  id: string,
  customerId: string,
  items: OrderItem[],
  status: OrderStatus,
  courierId: string | undefined,
  createdAt: string,
  x: number,
  y: number,
  method: 'card' | 'cash' = 'card',
  note?: string,
): Order => {
  const c = initialCustomers.find((u) => u.id === customerId)!;
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const deliveryFee = subtotal >= 200000 ? 0 : 12000;
  const discount = id === '102938' ? 15000 : 0;
  return {
    id,
    customerId,
    customer: c.name,
    phone: c.phone,
    address: ['Chilonzor, Bunyodkor 12', 'Yunusobod, Amir Temur 45', 'Mirzo Ulug\'bek, Universitet 8', 'Shayxontohur, Navoiy 33'][Number(id.slice(-1)) % 4],
    items,
    subtotal,
    deliveryFee,
    discount,
    total: subtotal + deliveryFee - discount,
    status,
    payment: status === 'cancelled' ? 'refunded' : method === 'cash' && status !== 'delivered' ? 'pending' : 'paid',
    method,
    courierId,
    createdAt,
    eta: '25-35 daqiqa',
    note,
    x,
    y,
  };
};

